x_comment(x_USUnitOfMeasure,"An instance of #$UnitOfMeasureTypeBySystem and a specialization of #$UnitOfMeasure.  Each instance of #$USUnitOfMeasure is a #$UnitOfMeasure that is or was standardly (but not necessarily commonly--see #$USUnitOfMeasure-Common) used in \"non-metric\" countries--primarily the #$UnitedStatesOfAmerica, but also (to a large extent) the #$UnitedKingdomOfGreatBritainAndNorthernIreland, the #$IrishRepublic, #$Burma, and #$Liberia.  It should be noted that there are some differences between the systems of measure used in the US and the UK.  (See, e.g., #$Gallon-US and #$Gallon-Imperial.)  However, these differences are minor enough that there is justication for treating the US and UK systems as a single system.  US units of money (#$Dollar-UnitedStates, #$Cent-UnitedStates, etc.) are NOT instances of #$USUnitOfMeasure; they are rather instances of (#$UnitOfMoneyTypeByGeopoliticalEntity #$UnitedStatesOfAmerica).  (The same goes, of course, for other \"non-metric\" countries.)  Note that some units of measure, e.g. #$SecondsDuration, #$Barrel-UnitOfVolume, #$Watt, and #$Byte, are instances of both #$USUnitOfMeasure and #$InternationalUnitOfMeasure.  (See #$UniversalUnitOfMeasure.)") :- x_cid(a65b12809424f3).
xc_microtheory(a65b12809424f3,x_WorldPoliticalGeographyDataMt).
