x_comment(x_CGSUnitOfMeasure,"A specialization of #$InternationalUnitOfMeasure and an instance of #$UnitOfMeasureTypeBySystem-Coherent.  Each instance of #$CGSUnitOfMeasure is a #$UnitOfMeasure which is part of the (obsolete) CGS system of measurement.  As its name suggests, CGS has three base units (see #$CGSUnitOfMeasure-Base): (#$Centi #$Meter), #$Gram, and #$SecondsDuration.  Derived units are those that can be defined algebraically from the base units or obtained by adding a #$MetricUnitPrefix to a CGS #$UnitOfMeasureNoPrefix. Some instances of #$CGSUnitOfMeasure are #$CentimetersPerSecond, #$Barye-UnitOfPressure, and #$Poise-UnitOfAbsoluteViscosity. Some non-instances are #$Kilometer, #$MetersPerSecond, and #$Pascal-UnitOfPressure.") :- x_cid(a65b12809424f4).
