x_comment(x_UnitOfMoneyOfGeopoliticalEntityFn,"An instance of #$UnaryFunction and #$CollectionDenotingFunction.  (#$UnitOfMoneyOfGeopoliticalEntityFn GPE) denotes the collection of instances of #$UnitOfMoney which are part of GPE's monetary system.\n<p>\nFor example, #$Dollar-UnitedStates, #$Cent-UnitedStates, and #$MillionDollars are instances of (#$UnitOfMoneyOfGeopoliticalEntityFn #$UnitedStatesOfAmerica); #$Euro is an instance of (#$UnitOfMoneyOfGeopoliticalEntityFn #$EuropeanUnion); #$Dollar-HongKong is an instance of (#$UnitOfMoneyOfGeopoliticalEntityFn #$HongKong).\n<p>\nIMPORTANT: When we say that a unit of money UNIT is part of GPE's monetary system, we mean that GPE is the issuer of all currency representing UNIT, i.e. (#$monetaryUnitIssuedBy UNIT GPE); we do not mean that GPE officially uses UNIT, i.e. (#$monetaryUnitUsedIn UNIT GPE)--although that is usually the case.  #$Euro is NOT an instance of (#$UnitOfMoneyTypeByGeopoliticalEntity #$Italy), even though #$Italy officially uses the #$Euro; for it is the #$EuropeanUnion, not #$Italy, that issues currency representing the #$Euro.") :- x_cid(a65b12809424f6).
