x_comment(x_SIUnitOfMeasure,"A specialization of #$InternationalUnitOfMeasure.  Each instance of #$SIUnitOfMeasure is a unit of measure which is officially included in the International System of Units (aka SI, for \"Systeme International\"), as decreed by the <i>Bureau International des Poids et Mesures</i>.  SI has seven base units (see #$SIUnitOfMeasure-Base): #$Meter, #$Kilogram, #$SecondsDuration, #$Ampere, #$Kelvin, #$Mole-ChemicalCountUnit, and #$Candela.  Derived units are those that can be defined algebraically from the base units or obtained by adding a #$MetricUnitPrefix to an SI #$UnitOfMeasureNoPrefix.  (There is one exception, due to the unfortunate fact that one base unit, the #$Kilogram, is a #$UnitOfMeasureWithPrefix. Because multiple prefixes may not be used, in the case of the #$Kilogram, #$MetricUnitPrefixes are used with the unit name #$Gram.)  Some instances of #$SIUnitOfMeasure are #$Meter, (#$Centi #$Meter), #$Kilogram, #$SquareMeter, #$Newton, #$Joule, #$Volt.  Some notable non-instances are #$MinutesDuration, #$Liter, #$MetricTon.  (For the looser, more colloquial notion of \"the metric system,\" see #$MetricUnitOfMeasure.)") :- x_cid(a65b12809424f7).
