x_comment(x_monetaryUnitUsedIn,"An instance of #$BinaryPredicate.  (#$monetaryUnitUsedIn UNIT GPE) means that the #$UnitOfMoney UNIT is officially used _throughout_ the #$GeopoliticalEntity GPE.  Note that (#$monetaryUnitUsedIn UNIT GPE) does not entail (#$monetaryUnitIssuedBy UNIT GPE) since many geopolitical entities use money (the currency representing which) they don't themselves issue.  For example, the #$Euro is used in #$Italy but but the currency representing the #$Euro is issued by the #$EuropeanUnion; #$Dollar-Australia is used in #$Tuvalu but the currency representing #$Dollar-Australia is issued by #$Australia; #$Dollar-UnitedStates is used in #$CityOfAustinTX but the currency representing the #$Dollar-UnitedStates is issued by the #$UnitedStatesOfAmerica.") :- x_cid(a65b12809424f8).
