x_comment('x_UniversalUnitOfMeasure-Common',"A specialization of #$UniversalUnitOfMeasure, #$InternationalUnitOfMeasure-Common, and #$USUnitOfMeasure-Common.  Each instance of #$UniversalUnitOfMeasure-Common is a #$UniversalUnitOfMeasure that is used commonly in everyday life and is familiar to the average person (of any country).  This is, of course, a vague criterion.  A good rule of thumb: If a unit would likely be used in a newspaper article without explanation or definition, it belongs in this collection.  Examples are #$MinutesDuration, #$WeeksDuration, #$Megabyte, #$Watt, #$Barrel-UnitOfVolume.  Some non-examples are #$Parsec, #$Angstrom, #$Mole-ChemicalCountUnit.") :- x_cid(a65b12809424f9).
