x_comment(x_StandardMonetaryUnitOfGeopoliticalEntityFn,"An instance of #$UnaryFunction and #$IndividualDenotingFunction.  (#$StandardMonetaryUnitOfGeopoliticalEntityFn GPE) denotes the standard or basic monetary unit of GPE--i.e., the unit in which amounts of GPE's money are standardly measured, and from which all other units of GPE's money are derived.  For example, (#$StandardMonetaryUnitOfGeopoliticalEntityFn #$UnitedStatesOfAmerica) denotes #$Dollar-UnitedStates, (#$StandardMonetaryUnitOfGeopoliticalEntityFn #$India) denotes #$Rupee-India, and (#$StandardMonetaryUnitOfGeopoliticalEntityFn #$EuropeanUnion) denotes #$Euro.  The corresponding predicate is standardMonetaryUnitOfGeopoliticalEntity.") :- x_cid(a65b12809424ff).
