x_comment('x_USUnitOfMeasure-Adjunct',"A specialization of #$USUnitOfMeasure.  Each instance of #$USUnitOfMeasure-Adjunct is a unit of measure which is partially (but only partially) defined from one or more instances of #$USUnitOfMeasure.  Examples are #$PeoplePerSquareMile, #$DollarsPerGallon, (#$Mega #$Mile).  #$PeoplePerSquareMile is defined in terms of #$Person, which is not a #$USUnitOfMeasure, and #$Mile, which is.  #$DollarsPerGallon is defined in terms of #$Dollar-UnitedStates, which is not a #$USUnitOfMeasure, and #$Gallon-US, which is.  (#$Mega #$Mile) is considered a #$USUnitOfMeasure-Adjunct because it is obtained by adding a #$MetricUnitPrefix to #$Mile, a #$USUnitOfMeasure.") :- x_cid(a65b1280942500).
