x_comment(x_Bonyad,"According to the Wikipedia (http://en.wikipedia.org/wiki/Bonyad), Bonyads are Iranian institutions that are ostensibly charitable trusts that have existed since the days of the late shah.  Endemically overstaffed, corrupt, and unprofitable, the Bonyads have command of a tremendous amount of wealth in Iranian society, controlling an estimated 40% of the country's GDP.  Always unacknowledged pawns of the Iranian government, after the Shiite revolution of 1979, the bonyads came under the direct control of the supreme leader and expediency council.  Some, like the sprawling Bonyad-e Janbazan va Mosztaz'afan, or 'Foundation of the Downtrodden', have since been used to channel money into some of the government's more questionable ends, such as Lebanese Hezbollah and the nuclear development program.") :- x_cid(a65b1280942501).
