x_comment(x_standardMonetaryUnitOfGeopoliticalEntity,"An instance of #$BinaryPredicate and #$FunctionalPredicate.  (#$standardMonetaryUnitOfGeopoliticalEntity GPE UNIT) means that the #$GeopoliticalEntity GPE has the #$UnitOfMoney UNIT as its standard or basic monetary unit--i.e., amounts of GPE's money are standardly measured in terms of UNIT, and all other units of GPE's money are derived from UNIT.  For example, (#$standardMonetaryUnitOfGeopoliticalEntity #$UnitedStatesOfAmerica #$Dollar-UnitedStates), (#$standardMonetaryUnitOfGeopoliticalEntity #$India #$Rupee-India), (#$standardMonetaryUnitOfGeopoliticalEntity #$EuropeanUnion #$Euro).  The corresponding function is #$StandardMonetaryUnitOfGeopoliticalEntityFn (q.v.).") :- x_cid(a65b1280942507).
