x_comment(x_UnitOfMoneyTypeByGeopoliticalEntity,"A collection of collections and a specialization of #$UnitOfMeasureTypeBySystem.  Each instance of #$UnitOfMoneyTypeByGeopoliticalEntity is a collection of units of money which are all part of the same geopolitical entity's monetary system.  For example, one instance of #$UnitOfMoneyTypeByGeopoliticalEntity is (#$UnitOfMoneyOfGeopoliticalEntityFn #$UnitedStatesOfAmerica), which has #$Dollar-UnitedStates, #$Cent-UnitedStates, and #$MillionDollars (among other things) as instances.  Note that not every #$GeopoliticalEntity has its own monetary system; most use the monetary system of some other #$GeopoliticalEntity (often, but not always, one of which they are a #$geopoliticalSubdivision).  For example, #$Italy uses the monetary system of the #$EuropeanUnion; #$Tuvalu uses the monetary system of #$Australia; #$CityOfAustinTX uses the monetary system of #$UnitedStatesOfAmerica. ") :- x_cid(a65b128094250a).
